cargo build --release -p v1-compiler --bin claim_batch 2>&1 | tail -1; for f in src/v2/test/claim/manual/scoped_type_reflection_conformance.dag src/v2/test/claim/long/decl_index_enumeration.dag dag/test/claim/decl_fact_value_projection_witness.dag dag/test/claim/decl_facts_initializer_projection_witness.dag; do [ -f $f ] || f=$(find . -name $(basename $f) | head -1); fns=$(grep -o "^test fn [a-z_0-9]*" $f | awk "{print \$3}" | paste -sd,); echo "== $f"; ./target/release/claim_batch --source-root dag --source-root src/v2 --entry $PWD/$f --functions $fns 2>&1 | grep -E "^(PASS|FAIL)"; echo "rc=${PIPESTATUS[0]}"; done; echo ==END
